content.content:
1	role: Aggregator
2	replicas: ${replicas}
3	podAnnotations:
4	  reloader.stakater.com/auto: "true"
5	service:
6	  enabled: true
7	  type: ClusterIP
8	  ports:
9	    - name: otlp-grpc
10	      port: 4317
11	      protocol: TCP
12	    - name: otlp-http
13	      port: 4318
14	      protocol: TCP
15	env:
16	  - name: DATADOG_API_KEY
17	    valueFrom:
18	      secretKeyRef:
19	        name: vector-datadog
20	        key: api_key
21	resources:
22	  requests:
23	    cpu: ${requests_cpu}
24	    memory: ${requests_memory}
25	  limits:
26	    cpu: "${limits_cpu}"
27	    memory: ${limits_memory}
28	customConfig:
29	  data_dir: /vector-data-dir
30	  api:
31	    enabled: true
32	    address: 127.0.0.1:8686
33	  sources:
34	    otlp_in:
35	      type: opentelemetry
36	      grpc:
37	        address: 0.0.0.0:4317
38	      http:
39	        address: 0.0.0.0:4318
40	  transforms:
41	    drop_audit:
42	      type: filter
43	      inputs:
44	        - otlp_in.logs
45	      condition: |
46	        msg = if is_string(.message) { string!(.message) } else { "" }
47	        !match(msg, r'Audit\s-\s.+') && !match(msg, r'"level":"audit"')
48	%{ if email_redaction_enabled ~}
49	    redact_emails_logs:
50	      type: remap
51	      inputs:
52	        - drop_audit
53	      source: |
54	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
55	        if is_string(.message) {
56	          .message = replace(string!(.message), email_re, "${email_redaction_replacement}")
57	        }
58	        if is_object(.attributes) {
59	          attrs, _err = object(.attributes)
60	          if is_object(attrs) {
61	            .attributes = map_values(object!(attrs)) -> |v| {
62	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
63	            }
64	          }
65	        }
66	    redact_emails_traces:
67	      type: remap
68	      inputs:
69	        - otlp_in.traces
70	      source: |
71	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
72	        if is_object(.attributes) {
73	          attrs, _err = object(.attributes)
74	          if is_object(attrs) {
75	            .attributes = map_values(object!(attrs)) -> |v| {
76	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
77	            }
78	          }
79	        }
80	        if is_object(.resource) {
81	          res, _err = object(.resource)
82	          if is_object(res) && is_object(res.attributes) {
83	            rattrs, _err2 = object(res.attributes)
84	            if is_object(rattrs) {
85	              .resource.attributes = map_values(object!(rattrs)) -> |v| {
86	                if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
87	              }
88	            }
89	          }
90	        }
91	    redact_emails_metrics:
92	      type: remap
93	      inputs:
94	        - otlp_in.metrics
95	      source: |
96	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
97	        if is_object(.attributes) {
98	          attrs, _err = object(.attributes)
99	          if is_object(attrs) {
100	            .attributes = map_values(object!(attrs)) -> |v| {
101	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
102	            }
103	          }
104	        }
105	        if is_object(.resource) {
106	          res, _err = object(.resource)
107	          if is_object(res) && is_object(res.attributes) {
108	            rattrs, _err2 = object(res.attributes)
109	            if is_object(rattrs) {
110	              .resource.attributes = map_values(object!(rattrs)) -> |v| {
111	                if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
112	              }
113	            }
114	          }
115	        }
116	%{ endif ~}
117	  sinks:
118	    datadog_logs:
119	      type: datadog_logs
120	      inputs:
121	        - ${email_redaction_enabled ? "redact_emails_logs" : "drop_audit"}
122	      default_api_key: $${DATADOG_API_KEY}
123	      site: ${datadog_site}
124	    datadog_traces:
125	      type: datadog_traces
126	      inputs:
127	        - ${email_redaction_enabled ? "redact_emails_traces" : "otlp_in.traces"}
128	      default_api_key: $${DATADOG_API_KEY}
129	      site: ${datadog_site}
130	    datadog_metrics:
131	      type: datadog_metrics
132	      inputs:
133	        - ${email_redaction_enabled ? "redact_emails_metrics" : "otlp_in.metrics"}
134	      default_api_key: $${DATADOG_API_KEY}
135	      site: ${datadog_site}
